choose.when:
SELECT	YMDHMS,
		CAST(YMDHMS AS DATETIME) AS DT_YMDHMS,


				ROUND(AVG(COUNT),2) AS RATE


				ROUND(AVG(RATE),2) AS RATE


FROM	CM_DEV_PERF_1
WHERE	YYYYMMDD BETWEEN #{date1} AND #{date2}
AND 	YMDHMS BETWEEN CONCAT(#{date1},#{time1},'00') AND CONCAT(#{date2},#{time2},'59')
AND 	ITEM_TYPE = #{itemType}
AND 	MNG_NO = #{mngNo}

	AND	ITEM_IDX = #{itemIdx}
	AND	MODULE_TMPL_OID_SEQ = #{moduleTmplOidSeq}

GROUP BY YMDHMS
ORDER BY YMDHMS

SELECT	CONCAT(YYYYMMDD, '000000') AS YMDHMS,
		CAST(YYYYMMDD AS DATE) AS DT_YMDHMS,
		ROUND(AVG(AVG_VAL),2) AS RATE,
		MIN(MIN_VAL) MIN_VAL,
		MAX(MAX_VAL) MAX_VAL
FROM	CM_DEV_PERF_3
WHERE	YYYYMMDD BETWEEN #{date1} AND #{date2}
AND 	ITEM_TYPE = #{itemType}
AND 	MNG_NO = #{mngNo}

	AND	ITEM_IDX = #{itemIdx}
	AND	MODULE_TMPL_OID_SEQ = #{moduleTmplOidSeq}



		AND TIME_ID = #{timeId}


		AND TIME_ID = 0


GROUP BY YYYYMMDD
ORDER BY YYYYMMDD

choose.otherwise:
SELECT	YMDHMS,
		CAST(YMDHMS AS DATETIME) AS DT_YMDHMS,
		ROUND(AVG(AVG_VAL),2) AS RATE,
		MIN(MIN_VAL) MIN_VAL,
		MAX(MAX_VAL) MAX_VAL
FROM	CM_DEV_PERF_2
WHERE	YYYYMMDD BETWEEN #{date1} AND #{date2}
AND 	YMDHMS BETWEEN CONCAT(#{date1},#{time1},'00') AND CONCAT(#{date2},#{time2},'59')
AND 	ITEM_TYPE = #{itemType}
AND 	MNG_NO = #{mngNo}

	AND	ITEM_IDX = #{itemIdx}
	AND	MODULE_TMPL_OID_SEQ = #{moduleTmplOidSeq}

GROUP BY YMDHMS
ORDER BY YMDHMS

choose.when:
SELECT	CONCAT(YYYYMMDD,'000000') AS YMDHMS,
		CAST(YYYYMMDD AS DATE) AS DT_YMDHMS,

FROM	CM_IF_PERF_3 A, CM_DEV20 B
WHERE	A.YYYYMMDD BETWEEN #{date1} AND #{date2}
AND 	A.MNG_NO = #{mngNo}
AND 	A.IF_IDX = #{ifIdx}
AND		A.MNG_NO = B.MNG_NO
AND		A.IF_IDX = B.IF_IDX


		AND A.TIME_ID = #{timeId}


		AND A.TIME_ID = 0


ORDER BY YYYYMMDD

mapper.sql:
(


    		SELECT YYYYMMDD, YMDHMS
		    FROM 	CM_DEV_PERF_DATE_1
		    WHERE 	MNG_NO = #{mngNo}
		    AND		YYYYMMDD BETWEEN #{date1} AND #{date2}
			AND 	YMDHMS BETWEEN CONCAT(#{date1},#{time1},'00') AND CONCAT(#{date2},#{time2},'59')


			SELECT YYYYMMDD, YMDHMS
		    FROM 	CM_DEV_PERF_DATE_2
		    WHERE 	MNG_NO = #{mngNo}
		    AND		YYYYMMDD BETWEEN #{date1} AND #{date2}
			AND 	YMDHMS BETWEEN CONCAT(#{date1},#{time1},'00') AND CONCAT(#{date2},#{time2},'59')


			SELECT YYYYMMDD, CONCAT(YYYYMMDD, '000000') AS YMDHMS
		    FROM 	CM_DEV_PERF_DATE_3
		    WHERE 	MNG_NO = #{mngNo}
		    AND		YYYYMMDD BETWEEN #{date1} AND #{date2}


					AND TIME_ID = #{timeId}


					AND TIME_ID = 0




)

